*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:       #0f1117;
  --bg-card:       #1a1d27;
  --bg-input:      #12141c;
  --border:        #2e3348;
  --border-focus:  #6c8aff;
  --border-error:  #f87171;
  --text-primary:  #e8eaf6;
  --text-secondary:#9096b8;
  --text-helper:   #9096b8;  /* #9096b8 on #1a1d27 ≈ 5.8:1 — was #7a7fa8 (4.3:1, failed AA) */
  --accent:        #6c8aff;
  --accent-hover:  #8aa0ff;
  --btn-bg:        #3d5bd8;  /* #fff on #3d5bd8 ≈ 5.7:1 */
  --btn-bg-hover:  #4a68e0;  /* #fff on #4a68e0 ≈ 4.8:1 */
  --error:         #f87171;
  --success-bg:    #0d2b1f;
  --success-border:#22c55e;
  --success-text:  #86efac;
  --radius:        8px;
  --transition:    180ms ease;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 2rem 1rem 4rem;
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 1rem; }

/* ===== Page layout ===== */
main {
  width: 100%;
  max-width: 520px;
}

.page-header { margin-bottom: 2rem; }

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.page-header p {
  margin-top: 0.375rem;
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

/* ===== Card ===== */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
}

/* ===== Required legend ===== */
.required-note {
  font-size: 0.8125rem;
  color: var(--text-helper);
  margin-bottom: 1.5rem;
}

.required-note .asterisk {
  color: var(--accent);
  font-weight: 700;
  margin-right: 0.2em;
}

/* ===== Form fields ===== */
.form-field { margin-bottom: 1.375rem; }

.form-field label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
}

.form-field label .required-marker {
  color: var(--accent);
  font-weight: 700;
  margin-left: 0.2em;
}

.form-field input {
  display: block;
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 0.9375rem;
  font-family: inherit;
  background: var(--bg-input);
  color: var(--text-primary);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
  -webkit-appearance: none;
}

.form-field input::placeholder { color: var(--text-helper); }

.form-field input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 138, 255, 0.25);
}

/* Error state */
.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
}

.form-field input[aria-invalid="true"]:focus {
  border-color: var(--border-error);
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.25);
}

/* ===== Helper & error text ===== */
.helper-text,
.error-text {
  margin-top: 0.3rem;
  font-size: 0.8125rem;
  line-height: 1.5;
}

.helper-text { color: var(--text-helper); }

.error-text {
  color: var(--error);
  display: none;
}

.error-text.visible { display: block; }

/* ===== Submit button ===== */
.submit-btn {
  display: block;
  width: 100%;
  margin-top: 1.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition), transform var(--transition);
  letter-spacing: 0.01em;
}

.submit-btn:hover { background: var(--accent-hover); }

.submit-btn:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

.submit-btn:active { transform: translateY(1px); }

/* ===== Status / live regions ===== */
.form-status {
  margin-top: 1.25rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9375rem;
  display: none;
}

.form-status.success {
  display: block;
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  color: var(--success-text);
}

/* sr-only: visually hidden but announced by AT */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Forced colors (Windows HC) ===== */
