  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 2rem 1rem 4rem;
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 1rem; }

/* ===== Page layout ===== */
main {
  width: 100%;
  max-width: 520px;
}

.page-header { margin-bottom: 2rem; }

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.page-header p {
  margin-top: 0.375rem;
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

