  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
}

.form-field label .required-marker {
  color: var(--accent);
  font-weight: 700;
  margin-left: 0.2em;
}

