.helper-text,
.error-text {
  margin-top: 0.3rem;
  font-size: 0.8125rem;
  line-height: 1.5;
}

.helper-text { color: var(--text-helper); }

.error-text {
  color: var(--error);
  display: none;
}

.error-text.visible { display: block; }

/* ===== Submit button ===== */
.submit-btn {
  display: block;
  width: 100%;
  margin-top: 1.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: #fff;
  background: var(--btn-bg);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition), transform var(--transition);
  letter-spacing: 0.01em;
}

.submit-btn:hover { background: var(--btn-bg-hover); }

.submit-btn:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

.submit-btn:active { transform: translateY(1px); }

/* ===== Status / live regions ===== */
.form-status {
  margin-top: 1.25rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9375rem;
  display: none;
}

