ToolExecutionCompleteResult(content="'use strict';

const form = document.getElementById('contact-form');

const fields = {
  fullName: {
    input:   document.getElementById('full-name'),
    error:   document.getElementById('full-name-error'),
    validate(val) {
      if (!val.trim()) return 'Error: Full name is required.';
      return null;
    }
  },
  email: {
    input:   document.getElementById('email'),
    error:   document.getElementById('email-error'),
    validate(val) {
      if (!val.trim()) return 'Error: Email address is required.';
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim()))
        return 'Error: Enter a valid email address, e.g. you@example.com.';
      return null;
    }
  },
  phone: {
    input:   document.getElementById('phone'),
    error:   document.getElementById('phone-error'),
