            name="full-name"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
            placeholder="Jane Smith"
          />
          <p id="full-name-error" class="error-text" aria-live="off"></p>
        </div>

        <!-- Email address -->
        <div class="form-field">
          <label for="email">
            Email address
            <span class="required-marker" aria-hidden="true">*</span>
            <span class="sr-only">(required)</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-describedby="email-error"
            placeholder="you@example.com"
          />
          <p id="email-error" class="error-text" aria-live="off"></p>
        </div>

        <!-- Phone number (optional) -->
        <div class="form-field">
          <label for="phone">
            Phone number
            <span class="sr-only">(optional)</span>
          </label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-help phone-error"
            placeholder="+1 (555) 000-0000"
          />
          <p id="phone-help" class="helper-text">
            Optional. Include country code, e.g. +1 (555) 000-0000.
          </p>
          <p id="phone-error" class="error-text" aria-live="off"></p>
        </div>

        <button type="submit" class="submit-btn">Send message</button>

      </form>

      <!-- Populated by JS after successful submit -->
      <div id="form-status" role="status" class="form-status"></div>
    </div>
  </main>

  <script>
'use strict';

const form = document.getElementById('contact-form');

const fields = {
  fullName: {
    input:   document.getElementById('full-name'),
    error:   document.getElementById('full-name-error'),
    validate(val) {
      if (!val.trim()) return 'Error: Full name is required.';
      return null;
    }
  },
  email: {
    input:   document.getElementById('email'),
    error:   document.getElementById('email-error'),
    validate(val) {
      if (!val.trim()) return 'Error: Email address is required.';
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim()))
        return 'Error: Enter a valid email address, e.g. you@example.com.';
      return null;
    }
  },
  phone: {
    input:   document.getElementById('phone'),
    error:   document.getElementById('phone-error'),
    validate(val) {
      if (!val.trim()) return null; // optional
      if (!/^\+?[\d\s\-().]{7,20}$/.test(val.trim()))
        return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000.';
      return null;
    }
  }
};

const statusRegion = document.getElementById('form-status');

function setFieldError(field, message) {
  field.input.setAttribute('aria-invalid', 'true');
  field.error.textContent = message;
  field.error.classList.add('visible');
}

