  field.input.removeAttribute('aria-invalid');
  field.error.textContent = '';
  field.error.classList.remove('visible');
}

// Clear error on input so the user gets immediate feedback while correcting
Object.values(fields).forEach(field => {
  field.input.addEventListener('input', () => {
    if (field.input.getAttribute('aria-invalid') === 'true') {
      const msg = field.validate(field.input.value);
      if (msg) {
        setFieldError(field, msg);
      } else {
        clearFieldError(field);
      }
    }
  });
});

form.addEventListener('submit', e => {
  e.preventDefault();

  // Clear any previous status
  statusRegion.textContent = '';
  statusRegion.classList.remove('success');

  let firstInvalid = null;

  Object.values(fields).forEach(field => {
    const msg = field.validate(field.input.value);
    if (msg) {
      setFieldError(field, msg);
      if (!firstInvalid) firstInvalid = field.input;
    } else {
      clearFieldError(field);
    }
  });

  if (firstInvalid) {
    firstInvalid.focus();
    return;
  }

  // Simulate successful submission
  form.reset();
  Object.values(fields).forEach(field => clearFieldError(field));

  statusRegion.textContent = "Your message has been sent. We'll be in touch soon.";
  statusRegion.classList.add('success');
});
